CREATE TABLE users (id BIGINT AUTO_INCREMENT PRIMARY KEY, email VARCHAR(320) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, clb_level VARCHAR(10) NOT NULL, daily_new_vocabulary_goal INT NOT NULL, created_at TIMESTAMP NOT NULL);
CREATE TABLE vocabulary_items (id BIGINT AUTO_INCREMENT PRIMARY KEY, normalized_term VARCHAR(255) NOT NULL UNIQUE, term VARCHAR(255) NOT NULL, type VARCHAR(30), phonetic VARCHAR(255), part_of_speech VARCHAR(255), definition_text TEXT, examples_json TEXT, collocations_json TEXT, enrichment_status VARCHAR(20) NOT NULL, failure_reason VARCHAR(500), created_at TIMESTAMP NOT NULL);
CREATE TABLE user_vocabularies (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, vocabulary_item_id BIGINT NOT NULL, learning_status VARCHAR(20) NOT NULL, created_at TIMESTAMP NOT NULL, CONSTRAINT uk_user_vocabulary UNIQUE(user_id,vocabulary_item_id), CONSTRAINT fk_uv_user FOREIGN KEY(user_id) REFERENCES users(id), CONSTRAINT fk_uv_item FOREIGN KEY(vocabulary_item_id) REFERENCES vocabulary_items(id));
CREATE TABLE revoked_tokens (token_hash VARCHAR(64) PRIMARY KEY, expires_at TIMESTAMP NOT NULL);
CREATE INDEX ix_user_vocabularies_user_created ON user_vocabularies(user_id, created_at);
